from kvquant.live4 import _Store, make_live_int4, held_bytes4, held_tensors
from kvquant import fused4
fused4.BACKEND = "triton"

def timeit(fn, warm=3, it=20):
    for _ in range(warm): fn()
    torch.cuda.synchronize(); s = torch.cuda.Event(enable_timing=True); e = torch.cuda.Event(enable_timing=True)
    s.record()
    for _ in range(it): fn()
    e.record(); torch.cuda.synchronize(); return s.elapsed_time(e) / it   # ms

def make_store(n, Hkv=4, D=128, seed=0):
    g = torch.Generator(device="cuda").manual_seed(seed)
    k = torch.randn(1, Hkv, n, D, device="cuda", generator=g, dtype=torch.bfloat16)
    k[..., :4] *= 8                                    # outlier channels, like real keys
    v = torch.randn(1, Hkv, n, D, device="cuda", generator=g, dtype=torch.bfloat16)
    ks, vs = _Store("k", 128), _Store("v", 128); ks.set(k); vs.set(v)
    return ks, vs, k, v

# ---------------- STEP 1: kernel correctness
if "1" not in SKIP:
    ok_all = True
    for n in (128, 640, 4096, 32768):
        for R in (7, 4):
            ks, vs, _, _ = make_store(n)
            q = torch.randn(1, 4, R, 128, device="cuda")
            nq = ks.n_q
            mt, lt, ot = fused4.region_triton(q, ks, vs, 128 ** -0.5, nq)
            mr, lr, orr = fused4.region_torch(q, ks, vs, 128 ** -0.5, nq)
            a, b = ot / lt[..., None], orr / lr[..., None]
            err = ((a - b).abs().max() / b.abs().max()).item()
            ok = err < 2e-2; ok_all &= ok
            print(f"KERNEL n={n} R={R} rel_max_err={err:.2e} {'OK' if ok else 'FAIL'}", flush=True)
            RES.setdefault("kernel", []).append({"n": n, "R": R, "rel_max_err": err})
    save()
    if not ok_all:
        print("STEP 1 FAIL: kernel does not match the reference, stopping", flush=True); sys.exit(1)

# ---------------- STEP 2: per-layer decode attention timing
if "2" not in SKIP:
    import torch.nn.functional as F
    for n in (4096, 16384, 32768, 65536):
        ks, vs, k, v = make_store(n)
        q = torch.randn(1, 28, 1, 128, device="cuda", dtype=torch.bfloat16)
        kq = torch.randn(1, 4, 1, 128, device="cuda", dtype=torch.bfloat16); vq = torch.randn_like(kq)
        kf, vf = torch.cat([k, kq], -2), torch.cat([v, vq], -2)
        t_bf16 = timeit(lambda: F.scaled_dot_product_attention(q, kf, vf, enable_gqa=True))
        def unfused():
            K = torch.cat([ks.get(), kq], -2); V = torch.cat([vs.get(), vq], -2)
            return F.scaled_dot_product_attention(q, K, V, enable_gqa=True)
        t_unf = timeit(unfused)
        qq = q[:, :, 0, :].reshape(1, 4, 7, 128).float()
        def fusedf():
            parts = [fused4.region_triton(qq, ks, vs, 128 ** -0.5, ks.n_q)]
            tk = ([ks.resid] if ks.resid is not None else []) + [kq]
            tv = ([vs.dequant(ks.n_q, vs.n_q, torch.float32)] if vs.n_q > ks.n_q else []) + [vq]
            parts.append(fused4._partial(qq, torch.cat([t.float() for t in tk], -2), torch.cat([t.float() for t in tv], -2), 128 ** -0.5))
            return fused4._merge(parts)
        t_fus = timeit(fusedf)
        row = {"ctx": n, "bf16_sdpa_us": round(t_bf16 * 1000, 1), "int4_unfused_us": round(t_unf * 1000, 1),
               "int4_fused_us": round(t_fus * 1000, 1)}
        RES.setdefault("attn", []).append(row); save()
        print("ATTN", json.dumps(row), f"| fused vs unfused x{t_unf / t_fus:.1f}, fused vs bf16 x{t_bf16 / t_fus:.2f}", flush=True)
        del ks, vs, k, v, kf, vf; torch.cuda.empty_cache()

# ---------------- model steps
MODEL = os.environ.get("MODEL", "Qwen/Qwen2.5-7B-Instruct")
if not {"3", "4", "5"} <= SKIP:
    from transformers import AutoTokenizer, AutoModelForCausalLM, DynamicCache
    tok = AutoTokenizer.from_pretrained(MODEL)
    model = AutoModelForCausalLM.from_pretrained(MODEL, dtype=torch.bfloat16, device_map="cuda").eval()
    cfg = model.config
    fused4.register()
    def set_impl(name): model.set_attn_implementation(name)
    def run(ids, arm, new=64):
        set_impl("kvq_int4" if arm == "int4_fused" else "sdpa")
        c = DynamicCache(config=cfg)
        if arm != "bf16": make_live_int4(c, fused=(arm == "int4_fused"))
        out_tok = []
        with torch.no_grad():
            o = model(ids, past_key_values=c, use_cache=True); t = o.logits[:, -1:].argmax(-1)
            torch.cuda.synchronize(); t0 = time.time()
            for _ in range(new):
                out_tok.append(t.item())
                o = model(t, past_key_values=c, use_cache=True); t = o.logits[:, -1:].argmax(-1)
            torch.cuda.synchronize()
        return (time.time() - t0) / new * 1000, out_tok, c

